mapper.select:
SELECT
    sku_id,sku_name, sku_description, category_id, sku_price,
    sale_count, sku_stock_count
FROM sku_master
WHERE is_deleted = 0

    AND sku_id = #{skuParamBo.skuId,jdbcType=BIGINT}


    AND sku_name = #{skuParamBo.skuName,jdbcType=VARCHAR}


    AND category_id = #{skuParamBo.categoryId,jdbcType=INTEGER}


    ORDER BY sale_count DESC

mapper.update:
UPDATE
    sku_master
SET
    sku_stock_count = sku_stock_count - #{saleCount,jdbcType=INTEGER},
    sale_count = sale_count + #{saleCount,jdbcType=INTEGER}
WHERE
    sku_id = #{skuId,jdbcType=BIGINT}
AND sku_stock_count >= #{saleCount,jdbcType=INTEGER}
